89: function definition(task, registry, inventory) {
90:   assert(runtimeTasks.has(task), 'Untrusted Task Context: use createTask or restoreTask');
91:   assert(task.registry_binding === digest(registry), 'Registry changed; explicitly migrate/reselect workflow');
92:   if (task.workflow_id) {
93:     const workflow = registry.workflows[task.workflow_id];
94:     assert(workflow, 'Unknown registered workflow');
95:     return workflow;
96:   }
97:   assert(inventory.has(task.skill_id), 'Unknown single Skill');
98:   return { stages: [{ id: 'task', type: 'skill', skill: task.skill_id, optional: false, condition: 'always', prerequisites: [], next: [], permission: 'request_scoped', stop_conditions: [] }], stop_conditions: [] };
99: }
100: 
101: export function createTask({ id, goal, acceptance, workflow_id = null, skill_id = null }, registry, inventory) {
102:   assert(id && goal && Array.isArray(acceptance) && acceptance.length, 'Goal and acceptance are required');
103:   assert(acceptance.every(item => typeof item === 'string' && item.length) && new Set(acceptance).size === acceptance.length, 'Acceptance IDs must be distinct strings');
104:   assert(Boolean(workflow_id) !== Boolean(skill_id), 'Choose one registered workflow or one existing Skill');
105:   const task = { schema_version: 2, id, goal, acceptance: copy(acceptance), workflow_id, skill_id,
106:     registry_binding: digest(registry), decisions: [], scope: { files: [], modules: [], interfaces: [] },
107:     risks: [], permission_refs: [], evidence: [], changes: [], unresolved: [], next_actions: [],
108:     current_stage: null, steps: {}, history: [] };
109:   runtimeTasks.add(task);
110:   for (const stage of definition(task, registry, inventory).stages) task.steps[stage.id] = { status: 'pending', attempts: 0, evidence_ids: [] };
111:   return task;
112: }
113: 
114: function evidenceFor(task, ids, host) {
115:   return ids?.length > 0 && ids.every(id => {
116:     const evidence = task.evidence.find(e => e.id === id);
117:     return evidence?.task_binding === taskBinding(task) && evidenceValidity(evidence, host).status === 'valid';
118:   });
119: }
120: function condition(task, name, host) {
121:   if (name === 'always') return true;
122:   const fact = host.conditions?.[name];
123:   return fact && typeof fact.value === 'boolean' && fact.reason && evidenceFor(task, fact.evidence_ids, host) ? fact.value : undefined;
124: }
125: function permission(skill, stage, task, host) {
126:   const metadata = host.inventory.get(skill);
127:   if (!metadata || !['draft', 'beta', 'stable'].includes(metadata.status)) return 'skill_unavailable';
128:   const request = host.requests?.[stage.id];
129:   if (!request) return 'operation_scope_missing';
130:   if (!Array.isArray(request.capabilities) || !request.capabilities.length) return 'capabilities_missing';
131:   if (stage.permission === 'write_scoped' && !request.capabilities.includes('write_files')) return 'write_scope_missing';
132:   if (stage.permission === 'read_only' && request.capabilities.includes('write_files')) return 'read_only_stage';
133:   for (const capability of request.capabilities) {
134:     if (!allowedCapabilities.includes(capability) || metadata.permissions?.[capability] !== true
135:         || host.capabilities?.[capability] !== true) return `capability_denied:${capability}`;
136:     const grants = host.grants?.filter(g => g.task_id === task.id && g.capability === capability && g.source
137:       && g.skills.includes(skill)) ?? [];
138:     if (!grants.length) return `user_authorization_missing:${capability}`;
139:     if (['read_files', 'write_files'].includes(capability)) {
140:       if (!request.paths?.length || request.paths.some(p => !safePath(p))) return 'explicit_paths_missing';
141:       if (request.paths.some(p => !grants.some(g => g.paths?.includes(p)))) return `path_not_authorized:${capability}`;
142:       try { for (const p of request.paths) checkPath(host.root, p); } catch { return 'unsafe_path'; }
143:     } else if (!request.operation || !grants.some(g => g.operations?.includes(request.operation))) return `operation_not_authorized:${capability}`;
144:   }
145:   const check = host.skillChecks?.[stage.id];
146:   if (!check?.source || check.request_binding !== digest(request) || check.skill_binding !== digest(metadata) || check.allowed !== true) return 'skill_scope_not_verified';
147:   if (request.capabilities.includes('run_shell_commands') && request.preflight !== 'safe') return 'command_preflight_missing';
148:   return null;
149: }
150: 
151: function potentiallyEffectful(stage, host) {
152:   return host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files') || stage.permission === 'write_scoped';
153: }
154: 
155: function writes(stage, host) {
156:   return stage.permission === 'write_scoped' || (stage.permission === 'request_scoped' && host.requests?.[stage.id]?.capabilities?.includes('write_files'));
157: }
158: 
159: export function reconciliationBinding(task, stageId, host) {
160:   return digest({ intent: taskBinding(task), stage: stageId, step: task.steps[stageId], request: host.requests?.[stageId] });
161: }
162: 
163: export function recoveryBinding(task, host) {
164:   const checkpoint = recovered.get(task);
165:   return checkpoint ? digest({ checkpoint, intent: taskBinding(task), requests: host.requests, skillChecks: host.skillChecks }) : null;
166: }
167: 
168: function requirement(task, requirement, host) {
169:   return task.evidence.some(e => e.claims?.includes(requirement.claim)
170:     && e.task_binding === taskBinding(task) && e.operation_binding === operationBinding(host)
171:     && (!requirement.skill || e.skill === requirement.skill)
172:     && (!requirement.kind || e.kind === requirement.kind)
173:     && (requirement.kind !== 'review' || (e.kind === 'review' && e.independent === true && host.reviewBinding && e.review_basis === host.reviewBinding))
174:     && evidenceValidity(e, host).status === 'valid');
175: }
176: 
177: function stepEvidence(task, stage, host) {
178:   const step = task.steps[stage.id];
179:   if (!evidenceFor(task, step.evidence_ids, host)) return false;
180:   const evidence = step.evidence_ids.map(id => task.evidence.find(e => e.id === id));
181:   const scoped = evidence.filter(e => e.skill === stage.skill && e.request_binding === digest(host.requests[stage.id]) && e.claims?.includes(`stage:${stage.id}`));
182:   if (!scoped.length) return false;
183:   if (stage.skill === 'safe-code-review' && !scoped.some(e => e.kind === 'review' && e.independent === true
184:       && e.review_basis && e.review_basis === host.reviewBinding)) return false;
185:   if (stage.skill === 'bug-root-cause-analysis' && !scoped.some(e => e.signal_ids?.length
186:       && e.signal_ids.every(id => task.evidence.some(signal => signal.id === id && signal.kind === 'signal' && signal.task_binding === taskBinding(task)
187:         && evidenceValidity(signal, host).status === 'valid')))) return false;
188:   return true;
189: }
190: 
191: function unresolvedFailures(task, host) {
192:   const unresolved = [];
193:   for (const failed of task.evidence.filter(e => e.task_binding === taskBinding(task) && e.kind === 'test' && e.result === 'fail')) {
194:     if (evidenceValidity(failed, host).status !== 'failed') continue;
195:     const resolution = host.failureResolutions?.get(digest(failed));
196:     const replacement = resolution?.source && task.evidence.find(e => e.id === resolution.replacement);
197:     const identity = e => digest({ command: e.command, cwd: e.cwd, bindings: e.bindings, environment: e.environment });
198:     if (!replacement || replacement.task_binding !== taskBinding(task) || replacement.kind !== 'test'
199:         || evidenceValidity(replacement, host).status !== 'valid' || identity(replacement) !== identity(failed)
200:         || !(Date.parse(replacement.recorded_at) > Date.parse(failed.recorded_at))) {
201:       unresolved.push(failed);
202:     }
203:   }
204:   return unresolved;
205: }
206: 
207: /** Recompute a decision every time. No imported context field grants execution authority. */
208: export function nextAction(task, host) {
209:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
210:   const workflow = definition(task, host.registry, host.inventory);
211:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
212:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };
213:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
214:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
215:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };
216:   const recovery = recoveryBinding(task, host);
217:   const recoveryCheck = recovery && host.recoveryChecks?.get(recovery);
218:   if (recovery && (!recoveryCheck?.source || recoveryCheck.reconciled !== true)) return { action: 'blocked', reason: 'recovered_execution_state_needs_reconciliation' };
219:   // Unknown effects cannot disappear when an optional predicate or prerequisite changes.
220:   const inflight = workflow.stages.find(stage => ['running', 'interrupted'].includes(task.steps[stage.id].status));
221:   if (inflight) return { stage: inflight.id, skill: inflight.skill, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
222:   const uncertain = workflow.stages.find(stage => task.steps[stage.id].effect_state === 'uncertain');
223:   if (uncertain) return { stage: uncertain.id, skill: uncertain.skill, action: 'validation_failed', reason: 'failed_operation_needs_reconciliation' };
224:   const completed = new Set();
225:   for (const stage of workflow.stages) {
226:     const step = task.steps[stage.id];
227:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
228:     if (step.request_binding && step.request_binding !== digest(host.requests?.[stage.id])) {
229:       return { stage: stage.id, skill: stage.skill, action: 'evidence_insufficient', reason: 'operation_scope_changed' };
230:     }
231:     const applies = condition(task, stage.condition, host);
232:     const decision = { stage: stage.id, skill: stage.skill };
233:     const stopAssessments = [...new Set([...(workflow.stop_conditions ?? []), ...stage.stop_conditions])].map(name => [name, condition(task, name, host)]);
234:     const stop = stopAssessments.find(([, value]) => value === true);
235:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop[0]}` };
236:     const unknownStop = stopAssessments.find(([, value]) => value === undefined);
237:     if (unknownStop) return { ...decision, action: 'evidence_insufficient', reason: `stop_condition_unknown:${unknownStop[0]}` };
238:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
239:     // Completed effects stay protected even when applicability changes. A new receipt
240:     // is not a reconciliation of the previous attempt's potentially different effects.
241:     const wasCompleted = ['completed', 'reused'].includes(step.status);
242:     const effectful = step.effect_state === 'known' || writes(stage, host)
243:       || host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files');
244:     if (stage.type === 'skill' && wasCompleted) {
245:       const denied = permission(stage.skill, stage, task, host);
246:       if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
247:       if (!stepEvidence(task, stage, host) && effectful) return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
248:     }
249:     if (!applies) {
250:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
251:       // Applicability must not erase a completed operation or its known effects.
252:       if (['completed', 'reused'].includes(step.status)) { completed.add(stage.id); continue; }
253:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };
254:       completed.add(stage.id); continue;
255:     }
256:     if (stage.type === 'gate') {
257:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
258:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
259:       for (const child of children) {
260:         const denied = permission(child.skill, child, task, host);
261:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
262:       }
263:       // Always re-evaluate gates against host grants, never reuse persisted approval.
264:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
265:       completed.add(stage.id); continue;
266:     }
267:     const denied = permission(stage.skill, stage, task, host);
268:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
269:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
270:       completed.add(stage.id); continue;
271:     }
272:     const failure = step.status === 'validation_failed';
273:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
274:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
275:     if (potentiallyEffectful(stage, host)) {
276:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
277:         .find(r => !requirement(task, r, host));
278:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
279:     }
280:     const candidate = host.reuse?.[stage.id];
281:     if (candidate) {
282:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate;
283:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
284:     }
285:     if ((writes(stage, host) || step.effect_state === 'known' || host.requests[stage.id].capabilities.some(c => c !== 'read_files')) && ['completed', 'reused'].includes(step.status)) {
286:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
287:     }
288:     const unresolved = unresolvedFailures(task, host).find(failed => {
289:       const repair = host.failureRepairs?.get(digest(failed));
290:       return !repair?.source || repair.stages?.[stage.id] !== digest(host.requests[stage.id]);
291:     });
292:     if (unresolved) return { ...decision, action: 'validation_failed', reason: 'unresolved_current_test_failure', evidence_id: unresolved.id };
293:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
294:   }
295:   if (completed.size !== workflow.stages.length) return { action: 'evidence_insufficient', reason: 'unresolved_dependencies' };
296:   const obligations = [
297:     ...task.acceptance.map(id => ({ claim: `acceptance:${id}` })),
298:     ...([...completed].some(id => {
299:       const stage = workflow.stages.find(s => s.id === id);
300:       return task.steps[id].status !== 'skipped'
301:         && ['feature-implementation', 'safe-fix-implementation', 'safe-test-implementation'].includes(stage.skill);
302:     }) ? [{ claim: 'behavior-validation', kind: 'test' }] : []),
303:     ...(host.deliveryRequirements ?? []),
304:     ...(host.risks ?? []).flatMap(r => {
305:       const rules = host.registry.coordination?.risk_requirements?.[r];
306:       return rules ? [...rules.before_write, ...rules.before_delivery] : [{ claim: `unclassified-risk:${r}` }];
307:     }),
308:   ];
309:   const failure = unresolvedFailures(task, host)[0];
310:   if (failure) return { action: 'validation_failed', reason: 'unresolved_current_test_failure', evidence_id: failure.id };
311:   const missing = obligations.filter(r => !requirement(task, r, host));
312:   if (task.unresolved.length || missing.length) return { action: 'evidence_insufficient', reason: 'delivery_not_proven', missing };
313:   return { action: 'complete', reason: 'applicable_stages_and_acceptance_proven', release_authorized: false };
314: }
315: 
316: function event(task, stage, status, reason) {
317:   task.current_stage = stage;
318:   task.history.push({ sequence: task.history.length + 1, stage, status, reason });
319: }
320: 
321: export function advance(task, host) {
322:   const action = nextAction(task, host);
323:   if (['skip', 'approve', 'reuse', 'execute'].includes(action.action)) {
324:     const step = task.steps[action.stage];
325:     step.status = { skip: 'skipped', approve: 'completed', reuse: 'reused', execute: 'running' }[action.action];
326:     step.reason = action.reason;
327:     if (['execute', 'reuse'].includes(action.action)) step.request_binding = digest(host.requests[action.stage]);
328:     if (action.action === 'execute') {
329:       step.attempts++;
330:       step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'uncertain' : 'none';
331:     }
332:     if (action.action === 'skip') {
333:       const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === action.stage);
334:       step.condition_binding = digest(host.conditions[stage.condition]);
335:     }
336:     if (action.action === 'reuse') step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'known' : 'none';
337:     if (action.evidence_ids) step.evidence_ids = action.evidence_ids;
338:     event(task, action.stage, step.status, action.reason);
339:   }
340:   task.next_actions = [action];
341:   return action;
342: }
343: 
344: export function finishStep(task, stageId, evidenceIds, host, failureReason = null) {
345:   const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === stageId);
346:   const step = task.steps[stageId];
347:   assert(stage && step?.status === 'running', 'Only a running stage may finish');
348:   assert(step.request_binding === digest(host.requests[stageId]), 'Operation scope changed while running');
349:   const denied = permission(stage.skill, stage, task, host);
350:   assert(!denied, denied);
351:   if (failureReason) { step.status = 'validation_failed'; step.reason = failureReason; step.evidence_ids = [...evidenceIds]; }
352:   else {
353:     const provisional = copy(task); provisional.steps[stageId].evidence_ids = evidenceIds;
354:     assert(stepEvidence(provisional, stage, host), 'Completion requires valid, scoped evidence and independent review');
355:     step.evidence_ids = [...evidenceIds]; step.status = 'completed'; step.effect_state = step.effect_state === 'none' ? 'none' : 'known';
356:   }
357:   event(task, stageId, step.status, failureReason || 'observed_completion');
358: }
