360: /** Reopening is an explicit host decision; only descendants are reopened.
361:  * Evidence is retained, so still-valid independent checks can be reused.
362:  */
363: export function reopen(task, stageId, host, { reason, source, safeToRetry = false } = {}) {
364:   assert(reason && source, 'Reopen requires a sourced reason');
365:   const workflow = definition(task, host.registry, host.inventory);
